    "explain": "ความกระด้างมาจากแคลเซียมและแมกนีเซียม ซึ่งมีผลต่อปลาไม่มากนัก แต่สำคัญมากต่อกุ้งเพราะต้องใช้แร่ธาตุเหล่านี้สร้างเปลือกใหม่หลังลอกคราบ ถ้าแร่ธาตุไม่พอกุ้งจะลอกคราบไม่ออกและอ่อนแอ\n\n❌ ทำไมข้ออื่นผิด\n— สลับข้อสรุปกัน ความกระด้างมีผลต่อกุ้งมากกว่าปลา\n— ตัวที่คุม pH คือความเป็นด่าง ไม่ใช่ความกระด้าง\n— ความกระด้างที่สูงขึ้นมีแนวโน้มลดความเป็นพิษ ไม่ใช่เพิ่ม\n\n💡 กระด้างเพื่อเปลือกกุ้ง ไม่ใช่เพื่อเกล็ดปลา",
    "verified": "Aqua Med Mid 86 p.7",
