    "explain": "เส้นข้างลำตัวเป็นอวัยวะรับความรู้สึกที่พาดยาวตามข้างตัวปลา ภายในมี neuromast cell ที่ตรวจจับการเคลื่อนไหวและแรงสั่นสะเทือนของน้ำรอบตัว ทำให้ปลาว่ายเป็นฝูงและหลบสิ่งกีดขวางได้\n\n❌ ทำไมข้ออื่นผิด\n— การรับกลิ่นเป็นหน้าที่ของรูจมูกและเซลล์รับกลิ่น ไม่ใช่เส้นข้างลำตัว\n— การควบคุมการลอยตัวเป็นหน้าที่ของถุงลมร่วมกับ gas gland\n— การสร้างเมือกเป็นหน้าที่ของ goblet cell ในชั้นหนังกำพร้า\n\n💡 neuromast คือเซ็นเซอร์คลื่นน้ำที่เรียงอยู่บนเส้นข้างลำตัว",
