    "answer": 3,
    "explain": "กุ้งก้ามกรามในสกุล Macrobrachium เป็น reservoir host ที่ติดเชื้อหัวเหลืองแล้วไม่แสดงอาการ ภาคกลางนิยมเลี้ยงกุ้งก้ามกรามร่วมกับกุ้งขาวในน้ำความเค็มต่ำ เชื้อจึงคงอยู่และระบาดในพื้นที่นี้มาก\n\n❌ ทำไมข้ออื่นผิด\n— ภาคกลางเป็นพื้นที่ความเค็มต่ำ ไม่ใช่ความเค็มสูง\n— อุณหภูมิไม่ใช่ปัจจัยที่อธิบายการกระจุกตัวของโรคในภาคกลาง\n— ไทยเป็นแหล่งที่มีการระบาดมาก่อน ไม่ได้รับเชื้อมาจากออสเตรเลีย\n\n💡 พาหะที่ไม่ป่วยคือแหล่งเก็บเชื้อที่มองไม่เห็น",
