    "answer": 0,
    "explain": "Vibrio ชอบน้ำเค็ม อุณหภูมิสูง และสารอินทรีย์ที่สะสมในตะกอนพื้นบ่อ ด้วยเหตุนี้จึงมีการนำกุ้งมาเลี้ยงในน้ำความเค็มต่ำลงเพื่อลดความเสี่ยง พร้อมกับควบคุมตะกอนและอินทรียวัตถุในบ่อ\n\n❌ ทำไมข้ออื่นผิด\n— ความเค็มต่ำและอินทรียวัตถุน้อยเป็นสภาพที่ลดความเสี่ยง ไม่ใช่เพิ่ม\n— ความเค็มต่ำไม่ใช่ปัจจัยส่งเสริม และออกซิเจนสูงเป็นผลดีต่อบ่อ\n— อุณหภูมิต่ำไม่ได้เอื้อต่อการเพิ่มจำนวนของเชื้อกลุ่มนี้\n\n💡 เค็ม ร้อน สกปรก คือสามคำที่ Vibrio ชอบที่สุด",
