    "explain": "Chilodonella เป็นโปรโตซัวมีขนที่ก่อโรคบริเวณเหงือกเป็นหลัก ทำให้เหงือกอักเสบและผลิตเมือกออกมามาก ปลาจึงหายใจลำบากและลอยขึ้นมาที่ผิวน้ำ\n\n❌ ทำไมข้ออื่นผิด\n— การถ่ายมูลเป็นเมือกขาวสัมพันธ์กับปัญหาในทางเดินอาหาร ไม่ใช่เชื้อนี้\n— แผลหลุมลึกที่ลำตัวเกิดจากเชื้อกลุ่มอื่น เช่น เชื้อราหรือแบคทีเรีย\n— ตาขุ่นและตาโปนเป็นลักษณะของการติดเชื้อ Streptococcus\n\n💡 Chilodonella คือปัญหาที่เหงือก ไม่ใช่ที่ผิวหนัง",
