    "explain": "axolotl เป็นสัตว์ที่อาศัยในน้ำเย็นตลอดชีวิต จึงพบภาวะ hyperthermia ได้บ่อยเมื่อเลี้ยงในอุณหภูมิที่สูงเกินไป อาการคือว่ายน้ำกระวนกระวายแล้วซึมและตาย การพยากรณ์โรคอยู่ในระดับแย่จนถึงแย่มาก\n\n❌ ทำไมข้ออื่นผิด\n— กบนาทนอุณหภูมิในเขตร้อนได้ดีกว่ามาก\n— คางคกไม่ใช่กลุ่มที่พบภาวะนี้เป็นปัญหาหลัก\n— ซาลาแมนเดอร์บกไม่ใช่ตัวอย่างที่ระบุ และการพยากรณ์โรคไม่ได้ดี\n\n💡 axolotl คือสัตว์น้ำเย็น เจอน้ำอุ่นเมื่อไรคือวิกฤต",
    "verified": "Aqua Med Mid 86 p.10",
