    "explain": "ปรสิตภายนอกของกุ้งเกาะตามรยางค์และผิวที่บางพอให้แสงผ่าน จึงเลือก pleopod เหงือก และ uropod มาวางบนแผ่นแก้วดูสด ทั้งสามบางพอให้เห็นโปรโตซัวที่เกาะอยู่ได้ทันทีโดยไม่ต้องย้อมสี\n\n❌ ทำไมข้ออื่นผิด\n— Carapace หนาเกินกว่าจะส่องผ่าน และกล้ามเนื้อใช้ดูรอยโรคภายในมากกว่า\n— Midgut และ hepatopancreas เป็นอวัยวะภายใน ใช้ตรวจเชื้อภายในไม่ใช่ปรสิตภายนอก\n— ลำไส้ใช้ดู gregarine ซึ่งเป็นปรสิตภายใน จึงคนละวัตถุประสงค์\n— การใส่ hepatopancreas เข้ามาทำให้ชุดนี้กลายเป็นการตรวจภายในไปด้วย\n\n💡 ปรสิตภายนอก ให้เลือกส่วนที่บางและอยู่นอกตัว",
