    "explain": "ทั้งปลาและกุ้งเป็นสัตว์เลือดเย็น อุณหภูมิน้ำจึงกำหนดอัตราเมแทบอลิซึมและความเร็วของการตอบสนองทางภูมิคุ้มกันโดยตรง น้ำเย็นทำให้ภูมิตกและติดเชื้อง่ายขึ้นในทั้งสองกลุ่ม\n\n❌ ทำไมข้ออื่นผิด\n— ปลาไม่มี lymph node เลย อวัยวะน้ำเหลืองหลักคือไทมัส ไตส่วนหน้า และม้าม\n— cell mediated immunity ที่แท้จริงเป็นของสัตว์มีกระดูกสันหลัง กุ้งมีแต่เซลล์จับกิน\n— กุ้งไม่มี plasma cell และไม่สร้าง immunoglobulin\n— กุ้งไม่มี MHC จึงไม่มีการนำเสนอแอนติเจนแบบจำเพาะ\n\n💡 กุ้งหยุดอยู่ที่ innate ส่วนปลาเริ่มมี adaptive แล้ว",
