    "explain": "ปริมาตรน้ำเท่ากับ 2 คูณ 3 คูณ 1 เท่ากับ 6 ลูกบาศก์เมตร ซึ่งเท่ากับ 6,000 ลิตร ค่า 1 ppm ของสารเหลวคือ 1 มิลลิลิตรต่อน้ำ 1,000 ลิตร ดังนั้น 25 ppm ในน้ำ 6,000 ลิตร เท่ากับ 25 คูณ 6 เท่ากับ 150 มิลลิลิตร\n\n❌ ทำไมข้ออื่นผิด\n— 15 มิลลิลิตรได้จากการคิดปริมาตรน้ำผิดไปสิบเท่า\n— 30 มิลลิลิตรได้จากการคูณ 25 ppm กับพื้นที่ผิวแทนปริมาตร\n— 90 มิลลิลิตรได้จากการใช้ระดับน้ำผิดหรือคิดที่ 15 ppm\n— 300 มิลลิลิตรได้จากการนับปริมาตรเป็นสองเท่า\n\n💡 จำสองบรรทัดนี้ 1 ลูกบาศก์เมตรเท่ากับ 1,000 ลิตร และ 1 ppm เท่ากับ 1 มิลลิลิตรต่อ 1,000 ลิตร",
