    "explain": "การตายจำนวนมากภายในคืนเดียวชี้ไปที่ปัญหาคุณภาพน้ำมากกว่าโรคติดเชื้อ โดยเฉพาะออกซิเจนตกตอนเช้ามืด แอมโมเนียสูง หรือแพลงก์ตอนตายยกบ่อ จึงต้องวัดออกซิเจนละลาย pH แอมโมเนียและไนไตรต์ก่อนตัดสินใจทำอย่างอื่น\n\n❌ ทำไมข้ออื่นผิด\n— ปลาที่ป่วยหนักไม่กินอาหาร การผสมยาจึงถึงเฉพาะตัวที่ยังแข็งแรง\n— การลงสารเคมีขณะออกซิเจนต่ำยิ่งซ้ำเติมให้ปลาตายเร็วขึ้น\n— การรีบจับขายโดยยังไม่รู้สาเหตุเสี่ยงต่อการส่งปลาที่มีสารตกค้างหรือเชื้อออกไป\n— การเพิ่มอาหารในบ่อที่ของเสียสะสมอยู่แล้วทำให้คุณภาพน้ำแย่ลงอีก\n\n💡 สัตว์น้ำตายเป็นกลุ่มในเวลาสั้น ให้คิดถึงน้ำก่อนคิดถึงเชื้อ",
