    "model_answer": "ตัวอย่างที่ตอบได้ หนึ่ง โรคเฮอร์ปีส์ไวรัสในปลาไน หรือ koi herpesvirus disease เกิดจากเชื้อ Cyprinid herpesvirus 3 อาการคือเหงือกซีดเป็นหย่อมและเปื่อย มีเนื้อตายและเซลล์เยื่อบุเหงือกเพิ่มจำนวนผิดปกติ ตาลึกโบ๋ ตายมากในช่วงอุณหภูมิ 18 ถึง 28 องศาเซลเซียส สอง โรคสเตรปโตคอกโคซิสในปลานิล เกิดจากเชื้อ Streptococcus agalactiae และ Streptococcus iniae อาการคือว่ายน้ำหมุนควงสว่าน ตาขุ่นและโปนสองข้าง มีจุดเลือดออกตามลำตัว มักระบาดช่วงอากาศร้อน สาม โรคตัวแดงดวงขาวในกุ้ง เกิดจาก white spot syndrome virus อาการคือมีจุดสีขาวใต้เปลือก ลำตัวออกสีแดงชมพู กุ้งลอยขอบบ่อและตายยกบ่อภายใน 3 ถึง 10 วัน อีกโรคที่ตอบได้คือโรคตายด่วนหรือ acute hepatopancreatic necrosis disease จากเชื้อ Vibrio parahaemolyticus ที่มียีนสร้างสารพิษ",
    "explain": "โจทย์ให้สามโรคพร้อมเชื้อและอาการ จึงควรวางเป็นสามย่อหน้าสั้น ย่อหน้าละสามบรรทัด ชื่อโรค เชื้อ อาการ\n\nควรเลือกโรคที่ต่างกลุ่มกัน คือปลาหนึ่งโรค กุ้งหนึ่งโรค และอีกโรคเลือกจากที่มั่นใจที่สุด จะได้ไม่พลาดเพราะจำเชื้อสับสนกัน\n\n💡 โรคระบาดสัตว์น้ำตามประกาศกระทรวงเกษตรและสหกรณ์อยู่ในหมวด ฉ.",
