    "explain": "✅ ถูก\n\nOtolith เป็นก้อนหินปูนในหูชั้นในที่วางอยู่บนกลุ่มเซลล์ขน เมื่อปลาเอียงตัวหรือเมื่อคลื่นเสียงเดินทางผ่านตัวปลา ก้อนหินปูนจะขยับไม่พร้อมกับเนื้อเยื่อรอบข้าง ทำให้เซลล์ขนถูกกระตุ้น ปลาจึงรับรู้ทั้งทิศทางของแรงโน้มถ่วงและคลื่นเสียง\n\nLateral line ทำงานด้วยหลักเดียวกันแต่อยู่ภายนอก มี neuromast cell รับแรงสั่นสะเทือนและการเคลื่อนไหวของน้ำรอบตัว ช่วยให้ปลารู้ทิศทางกระแสน้ำ หลบสิ่งกีดขวาง และว่ายรวมฝูงได้\n\n💡 otolith ยังใช้ประมาณอายุปลาได้จากวงปีที่ซ้อนกันอยู่ในเนื้อหินปูน",
